'use strict';
const $=s=>document.querySelector(s);
const fmt=n=>Number(n).toLocaleString('pt-BR');
const money=n=>Number(n).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const pct=(n,d)=>d?`${(100*n/d).toFixed(1).replace('.',',')}%`:'0,0%';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
let d, city='all',zone='all',section='all', territoryPage=0, benchmarkPage=0, activeTab='territory';
const cityByCode=new Map();
function options(el,rows,label){el.innerHTML='<option value="all">Todas'+(el.id==='city'?' as localidades':'')+'</option>'; for(const [value,text] of rows)el.add(new Option(text,value)); if(label)el.options[0].text=label;}
function selectedZones(){return city==='all'?d.zones:d.zones.filter(x=>x.code===city)}
function selectedSections(){return d.sections.filter(x=>(city==='all'||x.code===city)&&(zone==='all'||String(x.zone)===zone))}
function currentVotes(){if(section!=='all')return selectedSections().find(x=>String(x.section)===section)?.votes||0;if(zone!=='all')return selectedZones().find(x=>String(x.zone)===zone)?.votes||0;if(city!=='all')return cityByCode.get(city)?.votes||0;return d.candidate.votes}
function scopeName(){if(city==='all')return 'São Paulo · total estadual';let name=cityByCode.get(city)?.name||'Município';return name+(zone==='all'?'':` · zona ${zone}`)+(section==='all'?'':` · seção ${section}`)}
function setCity(value){city=value;zone='all';section='all';$('#city').value=city;refreshFilters();render()}
function refreshFilters(){const zones=city==='all'?[]:selectedZones();options($('#zone'),zones.map(x=>[String(x.zone),`Zona ${x.zone} · ${fmt(x.votes)} votos`]),'Todas as zonas');$('#zone').disabled=city==='all';if(zone!=='all'&&zones.some(x=>String(x.zone)===zone))$('#zone').value=zone;else zone='all';const sections=zone==='all'?[]:selectedSections();options($('#section'),sections.map(x=>[String(x.section),`Seção ${x.section} · ${fmt(x.votes)} votos`]),'Todas as seções');$('#section').disabled=zone==='all';if(section!=='all'&&sections.some(x=>String(x.section)===section))$('#section').value=section;else section='all'}
function bars(el,rows,limit=8){const top=rows.slice(0,limit),max=Math.max(...top.map(x=>x.v),1);el.innerHTML=top.map(x=>`<div class="barrow"><span title="${esc(x.n)}">${esc(x.n)}</span><div class="track"><div class="fill" style="width:${Math.max(x.v/max*100,x.v?2:0)}%"></div></div><b>${fmt(x.v)}</b></div>`).join('')||'<p class="muted">Sem votos neste recorte.</p>'}
function renderMetrics(){const votes=currentVotes(),sum=d.candidate.votes,rank=d.candidates.findIndex(x=>x.sq===d.candidate.sq)+1;$('#votes').textContent=fmt(votes);$('#scopeText').textContent=scopeName();$('#cityCount').textContent=city==='all'?fmt(d.cities.filter(x=>x.votes>0).length):votes>0?'1':'0';$('#citySub').textContent=city==='all'?'de 645 municípios de SP':'município no recorte';$('#share').textContent=pct(votes,sum);$('#rank').textContent=`${rank}ª por votos nominais entre ${fmt(d.candidates.length)} candidaturas`;$('#result').textContent='Suplente'}
function renderTerritory(){const local=cityByCode.get(city);let rows,title,unit,scope;
 if(city==='all'){rows=d.cities.map(x=>({n:x.name,v:x.votes,code:x.code}));title='Maiores municípios';unit='Município';scope='645 municípios · 333 com votos'}
 else if(zone==='all'){rows=selectedZones().map(x=>({n:`Zona ${x.zone}`,v:x.votes,zone:x.zone}));title=`Zonas · ${local.name}`;unit='Zona';scope=`${local.name} · ${rows.length} zonas`}
 else{rows=selectedSections().filter(x=>section==='all'||String(x.section)===section).map(x=>({n:`Seção ${x.section}`,v:x.votes,section:x.section}));title=section==='all'?`Seções · zona ${zone}`:`Seção ${section} · zona ${zone}`;unit='Seção';scope=`${local.name} · zona ${zone} · ${rows.length} seções no recorte`}
 rows.sort((a,b)=>b.v-a.v||a.n.localeCompare(b.n,'pt-BR'));$('#barsTitle').textContent=title;bars($('#bars'),rows,8);$('#placeHeader').textContent=unit;$('#tableScope').textContent=scope;
 const query=norm($('#territorySearch').value.trim());const shown=rows.filter(x=>norm(x.n).includes(query));const per=30;territoryPage=Math.min(territoryPage,Math.max(0,Math.ceil(shown.length/per)-1));const page=shown.slice(territoryPage*per,(territoryPage+1)*per),denom=currentVotes();$('#territoryRows').innerHTML=page.map(x=>`<tr><td>${esc(x.n)}</td><td class="num">${fmt(x.v)}</td><td class="num">${pct(x.v,denom)}</td></tr>`).join('')||'<tr><td colspan="3">Nenhum registro neste filtro.</td></tr>';$('#territoryPageInfo').textContent=`${fmt(shown.length)} registros · página ${territoryPage+1} de ${Math.max(1,Math.ceil(shown.length/per))}`;$('#territoryPrev').disabled=!territoryPage;$('#territoryNext').disabled=(territoryPage+1)*per>=shown.length;
 $('#scopeBadges').innerHTML=`<span class="badge">${fmt(d.zones.length)} zonas no arquivo</span><span class="badge">${fmt(d.sections.length)} seções com votos</span><span class="badge">${fmt(d.candidate.votes)} votos conciliados</span>`;
}
function renderInsights(){const all=d.candidate.votes,local=currentVotes(),positive=d.cities.filter(x=>x.votes>0),capital=d.cities.find(x=>x.name==='SÃO PAULO'),top5=d.cities.slice(0,5).reduce((s,x)=>s+x.votes,0),share=capital.votes/all*100;$('#capitalVotes').textContent=fmt(capital.votes);$('#elsewhereVotes').textContent=fmt(all-capital.votes);$('#donut').style.background=`conic-gradient(var(--blue) 0 ${share}%,#e3ebf4 ${share}% 100%)`;$('#donutValue').innerHTML=`${pct(capital.votes,all)}<small>na capital</small>`;$('#concentration').textContent=`Os cinco maiores municípios somam ${pct(top5,all)} dos votos.`;
 const list=[['Alcance geográfico',`${fmt(positive.length)} dos 645 municípios de SP registraram ao menos um voto nominal (${pct(positive.length,645)}).`],['Recorte escolhido',`${scopeName()} registra ${fmt(local)} votos, equivalentes a ${pct(local,all)} do total estadual.`],['Conferência de granularidade',`${fmt(d.sections.length)} seções com votos somam ${fmt(all)} e conferem com os registros das zonas.`]];
 $('#insights').innerHTML=list.map(([t,body])=>`<div class="insight"><b>${esc(t)}</b><p>${esc(body)}</p></div>`).join('')}
function renderBenchmark(){let rows=d.candidates.map((x,i)=>({...x,rank:i+1}));if($('#partyOnly').checked)rows=rows.filter(x=>x.party==='PL');const term=norm($('#candidateSearch').value.trim());if(term)rows=rows.filter(x=>norm(x.name).includes(term)||String(x.number).includes(term));const per=30;benchmarkPage=Math.min(benchmarkPage,Math.max(0,Math.ceil(rows.length/per)-1));$('#benchmarkRows').innerHTML=rows.slice(benchmarkPage*per,(benchmarkPage+1)*per).map(x=>`<tr class="${x.sq===d.candidate.sq?'highlight':''}"><td class="num">${fmt(x.rank)}ª</td><td>${esc(x.name)} <span class="muted">· ${esc(x.number)}</span></td><td>${esc(x.party)}</td><td class="num">${fmt(x.votes)}</td><td>${esc(x.result)}</td></tr>`).join('')||'<tr><td colspan="5">Nenhuma candidatura encontrada.</td></tr>';$('#benchmarkPageInfo').textContent=`${fmt(rows.length)} candidaturas · página ${benchmarkPage+1} de ${Math.max(1,Math.ceil(rows.length/per))}`;$('#benchmarkPrev').disabled=!benchmarkPage;$('#benchmarkNext').disabled=(benchmarkPage+1)*per>=rows.length}
function renderFinance(){const f=d.finance,r=f.receitas_candidatos,e=f.despesas_contratadas_candidatos;$('#revenue').textContent=money(r.total);$('#expenses').textContent=money(e.total);$('#difference').textContent=money(Number(r.total)-Number(e.total));bars($('#revenueBars'),Object.entries(r.subtotals).map(([n,v])=>({n,v:Number(v)})).sort((a,b)=>b.v-a.v),5);bars($('#expenseBars'),Object.entries(e.subtotals).map(([n,v])=>({n,v:Number(v)})).sort((a,b)=>b.v-a.v),6)}
function renderMethod(){const m=d.meta;$('#audit').textContent=`${fmt(m.rowsRead)} linhas de votação por município/zona em SP, ${fmt(d.zones.length)} registros da candidatura; ${fmt(m.sectionRowsRead)} linhas de seção em SP, ${fmt(d.sections.length)} seções com votos da candidatura. A soma por seção e por zona é ${fmt(d.candidate.votes)} sem divergência entre zonas.`;$('#hashes').innerHTML=[['Município/zona',m.zoneSha],['Seção SP',m.sectionSha],['Prestação de contas',m.financeSha]].map(([label,hash])=>`<p class="muted">${esc(label)}<br><span class="hash">${esc(hash)}</span></p>`).join('')}
function render(){renderMetrics();renderTerritory();renderInsights();renderBenchmark();window.mapModule?.render(city,zone)}
function renderHero(){const top=d.cities.slice(0,10),max=top[0].votes;document.querySelectorAll('.signal span').forEach((el,i)=>{el.style.height=`${Math.max(2,top[i].votes/max*100)}%`;el.title=`${top[i].name}: ${fmt(top[i].votes)} votos`})}
function events(){ $('#city').onchange=e=>{territoryPage=0;$('#territorySearch').value='';setCity(e.target.value)};$('#zone').onchange=e=>{zone=e.target.value;section='all';territoryPage=0;refreshFilters();render()};$('#section').onchange=e=>{section=e.target.value;territoryPage=0;render()};document.querySelectorAll('.pin').forEach(p=>p.onclick=()=>{const found=d.cities.find(x=>x.name===p.dataset.city);if(found)setCity(found.code)});$('#election').onchange=e=>{const old=e.target.value==='2024';$('#current').classList.toggle('hidden',old);$('#prior').classList.toggle('hidden',!old);$('#explorar').classList.toggle('hidden',old);for(const id of ['city','zone','section'])$('#'+id).disabled=old||(id==='zone'&&city==='all')||(id==='section'&&zone==='all')};document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{activeTab=b.dataset.tab;document.querySelectorAll('[data-tab]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-selected',String(x===b))});document.querySelectorAll('.panel').forEach(p=>p.classList.toggle('active',p.id===activeTab))});$('#territorySearch').oninput=()=>{territoryPage=0;renderTerritory()};$('#candidateSearch').oninput=()=>{benchmarkPage=0;renderBenchmark()};$('#partyOnly').onchange=()=>{benchmarkPage=0;renderBenchmark()};for(const [type,fn] of [['territory',renderTerritory],['benchmark',renderBenchmark]]){for(const [dir,step] of [['Prev',-1],['Next',1]]){$(`#${type}${dir}`).onclick=()=>{if(type==='territory')territoryPage+=step;else benchmarkPage+=step;fn()}}}}
async function init(){try{const response=await fetch('data.json',{cache:'no-cache'});if(!response.ok)throw Error(`HTTP ${response.status}`);d=await response.json();if(d.candidate.votes!==8416||d.sections.reduce((s,x)=>s+x.votes,0)!==d.candidate.votes||d.zones.reduce((s,x)=>s+x.votes,0)!==d.candidate.votes)throw Error('total inconsistente');cityByCode.clear();for(const x of d.cities)cityByCode.set(x.code,x);options($('#city'),d.cities.slice().sort((a,b)=>a.name.localeCompare(b.name,'pt-BR')).map(x=>[x.code,`${x.name} · ${fmt(x.votes)}`]),'Todos os municípios');events();renderHero();render();renderFinance();renderMethod();window.mapModule?.init(d,{chooseCity:setCity,chooseZone:(code,z)=>{if(city!==code)setCity(code);zone=String(z);section='all';refreshFilters();render()}});$('#status').innerHTML=`<b>Dados oficiais conciliados.</b> ${fmt(d.zones.length)} zonas e ${fmt(d.sections.length)} seções com votos conferidas; publicação estática extraída em ${d.meta.updated.split('-').reverse().join('/')}. Filtros não identificam eleitores.`}catch(err){$('#status').textContent=`Não foi possível carregar os dados do TSE (${err.message}). Tente atualizar a página.`;$('#status').style.background='#fff1e8'}}
init();
